/// Bytes-in → snapshot-out. Does not write the snapshot, set root/heads, or append an op.
/// `files` is the whole tree; `prev` lends ids only. Names resolve against what is parsed
/// here — never against `prev`, whose entities may be exactly what this edit deleted (a
/// reference kept bound to a gone id renders as `?`).
pub fn snapshot_files(
    store: &dyn Store,
    langs: &Langs,
    files: &BTreeMap<RelPath, Vec<u8>>,
    prev: Option<&Snapshot>,
    change: ChangeId,
) -> Result<Snapshot> {
    struct Parsed<'a> {
        path: RelPath,
        src: &'a [u8],
        tree: tree_sitter::Tree,
        raw: Vec<RawEntity>,
        lang: &'a dyn Lang,
        ids: Vec<EntityId>,
    }
    let mut parsed = Vec::new();
    let mut opaque = BTreeMap::new();
    let mut prev_ids = prev_ids(prev);
    for (path, src) in files {
        match langs.for_path(path) {
            Some(lang) => {
                let tree = parse(src, lang)?;
                let raw = extract(&tree, src, lang)?;
                let ids = assign_ids(&raw, path, &mut prev_ids);
                parsed.push(Parsed {
                    path: path.clone(),
                    src,
                    tree,
                    raw,
                    lang,
                    ids,
                });
            }
            // Manifests, lockfiles, recordings: stored as the file tail with no
            // entities so `svc init` on this repo still renders a tree cargo can build.
            None => {
                opaque.insert(path.clone(), src.clone());
            }
        }
    }
    // Prev is for assign_ids. Seeding names from it keeps deleted same-file
    // defs in the env, so a remaining call binds to a missing id and render
    // prints `?` (claude 03:34: absorb after deleting resolve_entity_in).
    let mut env = Env::default();
    for p in &parsed {
        for (i, ent) in p.raw.iter().enumerate() {
            if is_inherent_raw(&p.raw, i) {
                continue;
            }
            env.insert_def_in(&ent.name, ent.kind, p.ids[i], Some(&p.path));
        }
    }
    let mut entities = BTreeMap::new();
    let mut file_recs = BTreeMap::new();
    for p in &parsed {
        let (ents, file) = materialize(
            p.src,
            p.path.clone(),
            p.lang,
            store,
            &p.tree,
            &p.raw,
            &p.ids,
            &env,
        )?;
        entities.extend(ents);
        file_recs.insert(p.path.clone(), file);
    }
    for (path, src) in opaque {
        file_recs.insert(path, FileRecord::from_tail(store, &src)?);
    }
    Ok(Snapshot {
        parents: Vec::new(),
        predecessors: Vec::new(),
        change,
        entities,
        files: file_recs,
        conflicts: Vec::new(),
        message: String::new(),
    })
}

fn materialize(
    src: &[u8],
    path: RelPath,
    lang: &dyn Lang,
    store: &dyn Store,
    tree: &tree_sitter::Tree,
    raw: &[RawEntity],
    ids: &[EntityId],
    env: &Env,
) -> Result<(BTreeMap<EntityId, EntityRecord>, FileRecord)> {
    let mut entities = BTreeMap::new();
    // Clone once per file: `Env.names` is Arc, so this is not O(n) in the snapshot.
    // Filling `self_methods` only when the caller left it empty — `edit_def` fills it
    // from the snapshot, and the fragment being parsed has no siblings (opus 03:05).
    let mut local_env = env.clone();
    local_env.current_file = Some(path.clone());
    let caller_supplied = !env.self_methods.is_empty();
    let mut sibs: std::collections::HashMap<usize, std::collections::HashMap<String, EntityId>> =
        std::collections::HashMap::new();
    if !caller_supplied {
        for (j, sib) in raw.iter().enumerate() {
            if let Some(p) = sib.parent_idx {
                if is_callable_member(sib.kind) {
                    sibs.entry(p).or_default().insert(sib.name.clone(), ids[j]);
                }
            }
        }
    }
    for (i, ent) in raw.iter().enumerate() {
        let node = extract::find_node(tree.root_node(), ent.item_range)
            .ok_or_else(|| Error::Parse(format!("no node for {}", ent.name)))?;
        if !caller_supplied {
            local_env.self_methods = ent
                .parent_idx
                .and_then(|p| sibs.get(&p))
                .cloned()
                .unwrap_or_default();
        }
        let res = resolve(node, src, lang, &local_env)?;
        let children: Vec<(ByteRange, EntityId)> = ent
            .children
            .iter()
            .map(|&c| (raw[c].bytes_range, ids[c]))
            .collect();
        let own_name = ent.name_range.map(|r| (r, EntityId::SELF));
        let bytes = bytes::bytes_from_span(src, ent.bytes_range, &children, own_name, &res)?;
        let bytes_id = store.put_bytes_blob(&bytes)?;
        let child_spans: Vec<(ByteRange, EntityId)> = ent
            .children
            .iter()
            .map(|&c| (raw[c].item_range, ids[c]))
            .collect();
        let content = canonicalize(node, src, &res, &child_spans, &local_env, lang)?;
        let content_id = store.put_content(&content)?;
        let ordinal = raw
            .iter()
            .filter(|o| o.parent_idx == ent.parent_idx && o.item_range.start < ent.item_range.start)
            .count() as u32;
        entities.insert(
            ids[i],
            EntityRecord {
                name: ent.name.clone(),
                kind: ent.kind,
                parent: ent.parent_idx.map(|p| ids[p]),
                file: path.clone(),
                ordinal,
                content: content_id,
                bytes: bytes_id,
            },
        );
    }
    let roots: Vec<_> = raw
        .iter()
        .filter(|e| e.parent_idx.is_none())
        .cloned()
        .collect();
    let trailing = render_impl::trailing_for(src, &roots);
    Ok((entities, FileRecord::from_tail(store, &trailing)?))
}

pub fn render(snapshot: &Snapshot, store: &dyn Store, with_maps: bool) -> Result<Rendered> {
    let mut files = BTreeMap::new();
    let mut maps = with_maps.then(BTreeMap::new);
    for (path, rec) in &snapshot.files {
        let mut buf = Vec::new();
        for id in snapshot.file_roots(path) {
            let (bytes, map) = expand(snapshot, store, id, with_maps)?;
            buf.extend_from_slice(&bytes);
            if let (Some(maps), Some(map)) = (maps.as_mut(), map) {
                maps.insert(id, map);
            }
        }
        buf.extend_from_slice(&rec.tail(store)?);
        files.insert(path.clone(), buf);
    }
    Ok(Rendered { files, maps })
}

/// Structural deltas between two snapshots. An edited entity carries the class the
/// classifier assigns to old → new (rendered from `store`), never a placeholder. Files
/// are compared by their bytes outside entities, so an opaque file shows up as a whole.
pub fn diff(store: &dyn Store, prev: &Snapshot, next: &Snapshot) -> Result<Vec<Delta>> {
    let mut out = Vec::new();
    for (id, rec) in &next.entities {
        match prev.entities.get(id) {
            None => out.push(Delta::Added(*id)),
            Some(old) => {
                if old.name != rec.name {
                    out.push(Delta::Renamed {
                        id: *id,
                        from: old.name.clone(),
                        to: rec.name.clone(),
                    });
                }
                if old.parent != rec.parent {
                    out.push(Delta::Moved {
                        id: *id,
                        from_parent: old.parent,
                        to_parent: rec.parent,
                    });
                }
                if old.file != rec.file || old.ordinal != rec.ordinal {
                    let parent_kind = rec
                        .parent
                        .and_then(|pid| next.entities.get(&pid).map(|p| p.kind));
                    let layout_only = old.parent == rec.parent
                        && old.file == rec.file
                        && commutative_layout(rec.file.extension(), parent_kind, rec.kind);
                    if !layout_only {
                        out.push(Delta::Relocated {
                            id: *id,
                            from: (old.file.clone(), old.ordinal),
                            to: (rec.file.clone(), rec.ordinal),
                        });
                    }
                }
                if old.content != rec.content || old.bytes != rec.bytes {
                    out.push(Delta::Edited(*id, classify_entity(store, prev, next, *id)?));
                }
            }
        }
    }
    for (id, old) in &prev.entities {
        if !next.entities.contains_key(id) {
            out.push(Delta::Removed {
                id: *id,
                name: old.name.clone(),
            });
        }
    }
    for (path, rec) in &next.files {
        match prev.files.get(path) {
            None => out.push(Delta::FileAdded(path.clone())),
            Some(old) if old.trailing != rec.trailing => out.push(Delta::FileTail {
                path: path.clone(),
                whitespace_only: sans_whitespace(&old.tail(store)?) == sans_whitespace(&rec.tail(store)?),
            }),
            Some(_) => {}
        }
    }
    for path in prev.files.keys() {
        if !next.files.contains_key(path) {
            out.push(Delta::FileRemoved(path.clone()));
        }
    }
    Ok(out)
}

